-- The list can be anything that is a list, a lambda's result as well as a column. Row 2 has an empty
-- list, row 3 NULL elements among its values: nothing matches, and the sum of what is left is 10.
SELECT
  t.nr
, CASE WHEN CASE WHEN t.tags IS NULL THEN NULL ELSE CAST(MULTISET(SELECT upper(LA0.X) FROM (SELECT COLUMN_VALUE X, ROWNUM I FROM TABLE(t.tags) Z) LA0 ORDER BY LA0.I) AS SYS.ODCIVARCHAR2LIST) END IS NULL THEN NULL ELSE ((SELECT COUNT(*) FROM TABLE(CASE WHEN t.tags IS NULL THEN NULL ELSE CAST(MULTISET(SELECT upper(LA0.X) FROM (SELECT COLUMN_VALUE X, ROWNUM I FROM TABLE(t.tags) Z) LA0 ORDER BY LA0.I) AS SYS.ODCIVARCHAR2LIST) END) WHERE COLUMN_VALUE = 'RED') > 0) END AS has_red_upper
, CASE WHEN CASE WHEN t.scores IS NULL THEN NULL ELSE CAST(MULTISET(SELECT LA0.X FROM (SELECT COLUMN_VALUE X, ROWNUM I FROM TABLE(t.scores) Z) LA0 WHERE LA0.X > 5 ORDER BY LA0.I) AS SYS.ODCINUMBERLIST) END IS NULL THEN NULL ELSE (SELECT COUNT(*) FROM TABLE(CASE WHEN t.scores IS NULL THEN NULL ELSE CAST(MULTISET(SELECT LA0.X FROM (SELECT COLUMN_VALUE X, ROWNUM I FROM TABLE(t.scores) Z) LA0 WHERE LA0.X > 5 ORDER BY LA0.I) AS SYS.ODCINUMBERLIST) END)) END AS big
, (SELECT SUM(COLUMN_VALUE) FROM TABLE(CASE WHEN t.scores IS NULL THEN NULL ELSE CAST(MULTISET(SELECT LA0.X * 2 FROM (SELECT COLUMN_VALUE X, ROWNUM I FROM TABLE(t.scores) Z) LA0 ORDER BY LA0.I) AS SYS.ODCINUMBERLIST) END)) AS doubled_total
FROM
 check_complex t